// When each documentation chapter was last reviewed, shown under its title and
// published as dateModified. Kept out of src/content/docs-structure.js on
// purpose: that file is generated by scripts/extract-docs.mjs, and a
// regeneration would drop the dates.
//
// Update the chapter's date whenever you change its copy. Fast-moving pages
// need a date you can trust: the model lists in Key concepts, AI Reputation,
// the Glossary and the FAQ should be checked against the product monthly,
// even when nothing changes.
export const DOCS_UPDATED = {
  'introduction': '2026-11-11',
  'getting-started': '2026-11-11',
  'key-concepts': '2026-11-11',
  'credits': '2026-11-11',
  'ai-reputation': '2026-11-11',
  'keywords': '2026-11-11',
  'technical-audit': '2026-11-11',
  'test-reference': '2026-11-11',
  'roadmap': '2026-11-11',
  'content': '2026-11-11',
  'technical-fixes': '2026-11-11',
  'citations': '2026-11-11',
  'poli-ai': '2026-11-11',
  'site-connection': '2026-11-11',
  'settings': '2026-11-11',
  'glossary': '2026-11-11',
  'faq': '2026-11-11',
  'support': '2026-11-11',
  'whats-new': '2026-11-11',
};

/** ISO date for a chapter, or null when it has none. */
export const updatedOf = (slug) => DOCS_UPDATED[slug] ?? null;
